BEGIN;

UPDATE dynasties SET note = '可以指： *马楚，五代十国时一政权，位于今天湖南省。* 战国后期到秦汉时的地理概念，为楚国的南部边荒之地。' WHERE id = 'chu-nan';
UPDATE dynasties SET note = '北漢（951年2月24日－979年6月3日），由沙陀部建立，是中国五代十国時在今山西省北部、陕西省、河北省局部的政權，為十国之一。统治范围包括今山西北部、陕西、河北部分地区。' WHERE id = 'han-bei';
UPDATE dynasties SET note = '刘知远建后汉；951年郭威代汉。（947年—951年）' WHERE id = 'han-hou';
UPDATE dynasties SET note = '是五代十国时期的政权之一，位于现广东、广西、海南、香港、澳门以及越南北部（后失）。971年在北宋开国战争时被灭。' WHERE id = 'han-nan';
UPDATE dynasties SET note = '是中国历史上五代十国时期的第三个朝代，从后晋高祖石敬瑭936年灭后唐开国到契丹947年灭后晋一共经历了两个皇帝，總計11年。为与司马氏的晋朝相区别，又别称为石晋。' WHERE id = 'jin-hou';
UPDATE dynasties SET note = '又称南平、北楚，是五代时十国之一。值得注意的是，荊南雖被列为「十國」之一，但始終没有正式立国，始终是一个割據藩镇。' WHERE id = 'jingnan';
UPDATE dynasties SET note = '梁（502年5月1日－557年11月12日），史稱南梁、蕭梁、前梁、南朝梁，是中国历史上南北朝时期南朝的第三个朝代，由南齐宗室蕭衍称帝，改國號為梁，首都建康（今江苏南京）。永元二年（501年），萧衍攻入南齐首都建康，梁天监元年（502年），萧衍强迫齐和帝萧宝融禅位，萧衍正式称……。' WHERE id = 'liang-nan';
UPDATE dynasties SET note = '闽（），五代十国的十國之一，由闽王王審知於909年建立。926年，嗣王王延翰称大闽国王，正式建立闽国。' WHERE id = 'min-fujian';
UPDATE dynasties SET note = '齊（479年—502年）是中国历史上南北朝时期南朝第二个朝代。史称南齐（以与北朝的北齐相区别）或萧齐，有时亦与南梁合称“齐梁”。' WHERE id = 'qi-nan';
UPDATE dynasties SET note = '是中国五代十国时期由王建建立的政权，十国之一。前蜀疆域辽阔，东控荆襄，南通南诏，西达维州（今四川理县），北过秦州（今甘肃天水），占领了今天四川、湖北、陕西以及甘肃大部，重庆、贵州以及云南部分地区，方圆数千里。' WHERE id = 'shu-qian';
UPDATE dynasties SET note = '是五代十國的十國之一，定都金陵府，建隆二年（961年）短暂迁都南昌府（号“南都”），歷時38年，有烈祖李昪、元宗李璟和後主李煜三位君主。南唐开国皇帝李昪原名徐知诰，为杨吴权臣徐温养子。' WHERE id = 'tang-nan';
UPDATE dynasties SET note = '吴（）是五代时期十国之一，为楊隆演所建，又称杨吴、南吴、弘農、淮南。唐昭宗景福元年（892年）杨行密为唐淮南节度使，据扬州。' WHERE id = 'wu-shi';
UPDATE dynasties SET note = '钱镠据两浙；978年钱俶纳土归宋。（907年—978年）' WHERE id = 'wuyue';
UPDATE persons SET bio = '愛育黎拔力八達（；，，梵语意为寿山），中国元朝皇帝及蒙古帝国大汗，于公元1311年4月至1320年3月在位，共计近9年。元仁宗早年助兄长海山即位，被海山立为皇太子（元朝的皇位继承人一律称皇太子），相约兄终弟及，叔侄相传。' WHERE id = 'ayurbarwada';
UPDATE persons SET bio = '后周世宗，励精图治，北伐南征。在后周（954年—959年）在位。' WHERE id = 'chai-rong';
UPDATE persons SET bio = '周恭帝郭宗训（），五代时期后周皇帝，周世宗郭荣第四子。显德六年（959年）封为梁王。' WHERE id = 'chai-zongxun';
UPDATE persons SET bio = '陳武帝陈霸先（），字兴国，小字法生，吴兴郡长城县（今浙江长兴）人，南北朝時代陳朝開國皇帝。557年接受梁敬帝萧方智的禪位建立陳朝，557年－559年在位。' WHERE id = 'chen-baxian';
UPDATE persons SET bio = '陈废帝，为叔父陈顼所废。在南陈（566年—568年）在位。' WHERE id = 'chen-bozong';
UPDATE persons SET bio = '陈文帝，陈霸先侄，励精图治。在南陈（559年—566年）在位。' WHERE id = 'chen-qian';
UPDATE persons SET bio = '陈后主，玉树后庭花，隋灭陈。在南陈（582年—589年）在位。' WHERE id = 'chen-shubao';
UPDATE persons SET bio = '陈宣帝，陈朝中兴，北伐齐。在南陈（568年—582年）在位。' WHERE id = 'chen-xu';
UPDATE persons SET bio = '南平貞懿王高保融（），字德長，五代時期荊南君主（渤海郡王、南平王）。為高從誨之第三子。' WHERE id = 'gao-baorong';
UPDATE persons SET bio = '荆南第四代君主。在荆南（960年—962年）在位。' WHERE id = 'gao-baoxu';
UPDATE persons SET bio = '荆南第二代君主，高季兴之子。在荆南（928年—948年）在位。' WHERE id = 'gao-conghe';
UPDATE persons SET bio = '北齐幼主，北齐末代，为北周所俘。在北齐（577年—578年）在位。' WHERE id = 'gao-heng';
UPDATE persons SET bio = '荆南末主，纳土归宋。在荆南（962年—963年）在位。' WHERE id = 'gao-jichong';
UPDATE persons SET bio = '荆南（南平）开国，据江陵。在荆南（924年—928年）在位。' WHERE id = 'gao-jixing';
UPDATE persons SET bio = '北齐后主，宠信小人，为北周所灭。在北齐（569年—577年）在位。' WHERE id = 'gao-wei';
UPDATE persons SET bio = '齊孝昭帝高演（），字延安，勃海郡蓨县（今河北省衡水市景县）人，北齐第三任皇帝（560年－561年在位）。他是東魏权臣高欢第六子，文宣帝同母弟，在位一年。' WHERE id = 'gao-yan';
UPDATE persons SET bio = '北齐废帝，文宣帝子，为叔父高演所废杀。在北齐（559年—560年）在位。' WHERE id = 'gao-yin';
UPDATE persons SET bio = '齊武成帝高湛（），小字步落稽，勃海郡蓨县（今河北省衡水市景县）人，北齐第四位皇帝，561－565年在位，565 - 569年居太上皇，在位四年，实际掌权七年餘。東魏權臣高歡第九子，文襄帝高澄、文宣帝高洋、孝昭帝高演之同母弟。' WHERE id = 'gao-zhan';
UPDATE persons SET bio = '周太祖郭威（），字文仲，小名“郭雀兒”，籍貫邢州堯山（今河北隆堯）。五代時期後周開國皇帝（951年—954年）。' WHERE id = 'guo-wei';
UPDATE persons SET bio = '爱新觉罗·弘历，清高宗，雍正帝第四子。乾隆朝平定准噶尔、回部等地，编纂《四库全书》；在位六十年后禅位，仍以太上皇训政至1799年。' WHERE id = 'hongli';
UPDATE persons SET bio = '爱新觉罗·皇太极，努尔哈赤第八子，清太宗。1626年继承汗位，改革政制、整编八旗；1636年改国号为大清并称帝，为清军入关奠定基础。' WHERE id = 'huang-taiji';
UPDATE persons SET bio = '元寧宗懿璘质班（，，）是元朝皇帝，蒙古帝国大汗。1332年10月23日－1332年12月14日在位，在位2个月。' WHERE id = 'irinchibal';
UPDATE persons SET bio = '海山（；），孛儿只斤氏，是中国元朝皇帝及蒙古帝国大汗，于1307年6月至1311年1月在位近4年。1309年2月，群臣为其上汉文尊号统天继圣钦文英武大章孝皇帝。' WHERE id = 'khayishan';
UPDATE persons SET bio = '元明宗，文宗之兄，即位仅一月被害。在元（1329年—1329年）在位。' WHERE id = 'khoshila';
UPDATE persons SET bio = '唐穆宗次子，唐敬宗之弟，唐武宗之兄。827年至840年在位，后世称唐文宗。' WHERE id = 'li-ang';
UPDATE persons SET bio = '南唐烈祖李（），字正倫，小字彭奴，五代十國時期南唐開國皇帝，徐州人，原名徐知誥，是南吳權臣徐溫養子，南唐第1任國主兼開國皇帝。李昪登基後便励精图治，使南唐的國力大為提升。' WHERE id = 'li-bian';
UPDATE persons SET bio = '初名怡，封光王后以皇太叔身份继位。846年至859年在位，励行改革，开创晚唐少有的稳定局面，史称大中之治。' WHERE id = 'li-chen-tang';
UPDATE persons SET bio = '原名李淳，唐顺宗之子。805年至820年在位，任用将相削平藩镇，促成元和中兴。' WHERE id = 'li-chun';
UPDATE persons SET bio = '夏桓宗，在位十三年，蒙古势力崛起之际。在西夏（1193年—1206年）在位。' WHERE id = 'li-chunyou';
UPDATE persons SET bio = '后唐闵帝，在位仅三个月。在后唐（933年—934年）在位。' WHERE id = 'li-conghou';
UPDATE persons SET bio = '后唐末帝，为石敬瑭联契丹所灭。在后唐（934年—937年）在位。' WHERE id = 'li-congke';
UPDATE persons SET bio = '初名温，唐宣宗长子。859年至873年在位，晚唐国势继续衰落。' WHERE id = 'li-cui';
UPDATE persons SET bio = '唐莊宗李存（），山西应县人，沙陀族，本姓朱邪，因其父是河東節度使李克用受唐懿宗赐姓而改姓李，諱存-{勖}-，亦作存，唐光启元年正月（885年12月）生于山西应县（一说晋阳宫），五代時期后唐开国皇帝。小名“亚子”，藝名“李天下”，以勇猛闻名。' WHERE id = 'li-cunxu';
UPDATE persons SET bio = '唐高宗与武则天之子，两度即位、两度禅让。684年至690年及710年至712年在位，第二次退位后尊为太上皇。' WHERE id = 'li-dan';
UPDATE persons SET bio = '夏献宗，1223年嗣位，蒙古持续围攻。在西夏（1223年—1226年）在位。' WHERE id = 'li-dewang';
UPDATE persons SET bio = '马嵬驿后即位，借助郭子仪等平定安史之乱。756年至762年在位。' WHERE id = 'li-heng';
UPDATE persons SET bio = '原名宥，唐宪宗第三子。820年至824年在位，后世称唐穆宗。' WHERE id = 'li-heng-mu';
UPDATE persons SET bio = '南唐元宗李璟（），字伯玉，原稱徐景通、徐瑶，南唐建立後，復本姓李，改名璟。對後周稱臣後，又為避後周信祖諱，而改名景，徐州人，南唐烈祖長子。' WHERE id = 'li-jing-nantang';
UPDATE persons SET bio = '唐代宗长子。779年至805年在位，前期整顿财政、平定叛乱，晚年削藩失利。' WHERE id = 'li-kuo';
UPDATE persons SET bio = '唐睿宗第三子，712年至756年在位。前期开创开元盛世，后期怠政并爆发安史之乱，退位后为太上皇。' WHERE id = 'li-longji';
UPDATE persons SET bio = '唐明宗李亶（），初名嗣源，小名邈佶烈，应州金城县（今山西省应县）人，沙陀族，五代十国时期后唐第二位皇帝（926年6月3日－933年12月15日在位），在位八年。唐河东节度使李克用之养子，生父為汾州刺史李霓。' WHERE id = 'li-siyuan';
UPDATE persons SET bio = '唐德宗长子。805年即位，在位不足一年，因病禅位于唐宪宗，后世称唐顺宗。' WHERE id = 'li-song';
UPDATE persons SET bio = '原名李哲，两度即位。684年初及705年至710年在位，复位后恢复唐朝，最终在政变中去世。' WHERE id = 'li-xian';
UPDATE persons SET bio = '唐懿宗第五子，873年至888年在位。其时爆发黄巢之乱，长安一度陷落，僖宗曾避难入蜀。' WHERE id = 'li-xuan-tang';
UPDATE persons SET bio = '原名李瀍，唐穆宗第五子。840年至846年在位，推行会昌灭佛等政策，晚年服丹药去世。' WHERE id = 'li-yan-tang';
UPDATE persons SET bio = '唐懿宗第七子，888年至904年在位。曾试图削弱藩镇，却长期受军阀挟制，最终被朱温劫持杀害。' WHERE id = 'li-ye-tang';
UPDATE persons SET bio = '原名從嘉，後改名煜，字重光，號鍾山隐士、钟峰隐者、白蓮居士、蓮峰居士等，為南唐末代国主，史稱李後主。南唐亡后，被掳入宋，封违命侯，后被宋太宗毒死。' WHERE id = 'li-yu-nantang';
UPDATE persons SET bio = '唐肃宗庶长子，曾任天下兵马元帅并收复长安。762年至779年在位，后世称唐代宗。' WHERE id = 'li-yu-tang';
UPDATE persons SET bio = '字叔德，唐朝开国皇帝。618年至626年在位，建立唐朝并统一关中及中原大部，后禅位于李世民。' WHERE id = 'li-yuan';
UPDATE persons SET bio = '唐穆宗长子，15岁即位。824年至826年在位，后世称唐敬宗，年少时为宦官所弑。' WHERE id = 'li-zhan';
UPDATE persons SET bio = '唐太宗第九子，649年至683年在位。前期有永徽之治，后与武则天共同执政，唐朝疆域在其时期达到高峰。' WHERE id = 'li-zhi';
UPDATE persons SET bio = '原名祚，唐昭宗第九子。904年至907年在位，朱温逼其禅位，唐朝随之灭亡。' WHERE id = 'li-zhu-tang';
UPDATE persons SET bio = '夏神宗，蒙古反复侵夏，国力日衰。在西夏（1211年—1223年）在位。' WHERE id = 'li-zunxu';
UPDATE persons SET bio = '刘驁（），字太孫。漢朝皇帝，其正式諡号为「孝成皇帝」，后世省略「孝」字称「汉成帝」，汉元帝長子，母孝元皇后王政君（王莽姑母）。' WHERE id = 'liu-ao';
UPDATE persons SET bio = '汉高祖劉邦（），字季，原名刘季，沛丰邑中阳里（今江蘇省豐縣）人，中国秦末汉初的軍事家、政治家，汉朝开国皇帝，也是中国历史上第一位平民阶级出身的皇帝。秦末世乱之际，其參與以楚國為首的反秦起義，成為諸侯之一。' WHERE id = 'liu-bang';
UPDATE persons SET bio = '刘保（），东汉皇帝（125年12月16日－144年9月20日在位），其正式諡號為「孝順皇帝」，後世省略「孝」字稱「漢順帝」。汉安帝和宫人李氏之子。' WHERE id = 'liu-bao';
UPDATE persons SET bio = '汉后少帝，灵帝长子，为董卓所废。在东汉（189年—189年）在位。' WHERE id = 'liu-bian';
UPDATE persons SET bio = '南汉殇帝，在位仅两年。在南汉（942年—943年）在位。' WHERE id = 'liu-bin';
UPDATE persons SET bio = '刘炳（漢安二年至永嘉元年正月初六戊戌日，即公元），东汉皇帝（建康元年八月初六庚午日至永嘉元年正月初六戊戌日，即西元144年9月20日－145年2月15日在位），东汉第九位皇帝，在位僅五個月，享年还不满三周岁，其正式諡號為「孝沖皇帝」，後世省略「孝」字稱「漢沖帝」。' WHERE id = 'liu-bing';
UPDATE persons SET bio = '南汉末帝，为宋所灭。在南汉（958年—971年）在位。' WHERE id = 'liu-chang';
UPDATE persons SET bio = '后汉隐帝，后汉末代，为郭威所代。在后汉（948年—951年）在位。' WHERE id = 'liu-chengyou';
UPDATE persons SET bio = '北汉末帝，为宋所灭。在北汉（968年—979年）在位。' WHERE id = 'liu-jiyuan';
UPDATE persons SET bio = '宋孝武帝，平讨元凶，后期穷兵黩武。在刘宋（453年—464年）在位。' WHERE id = 'liu-jun';
UPDATE persons SET bio = '可以指： * 刘钧 (陈王)，东汉陈王 * 刘钧 (北汉)，五代十国时北汉睿宗 * 刘钧 (围棋)，世界业余围棋锦标赛冠军 * 刘钧 (演员)，中国演员 * 刘钧 (香港)，招商銀行香港分行行長暨招商永隆銀行行政總裁。' WHERE id = 'liu-jun-bei';
UPDATE persons SET bio = '漢平帝劉（公元），原名劉箕子，后改名衎，漢朝皇帝（公元前1年10月17日－公元6年2月3日在位），其正式諡號為「孝平皇帝」，後世省略「孝」字稱「漢平帝」。' WHERE id = 'liu-kan';
UPDATE persons SET bio = '北汉世祖，据太原。在北汉（951年—954年）在位。' WHERE id = 'liu-min';
UPDATE persons SET bio = '刘啓（），为漢朝皇帝（前157年7月14日－前141年3月9日在位），在位16年，享年48岁，其正式諡號為「孝景皇帝」，後世省略「孝」字稱「漢景帝」，景帝後元三年正月甲子（前141年3月9日）崩于未央宮，二月癸酉（3月18日）葬于阳陵（今陕西高陵县西南）。为汉文帝刘恒長子，母……。' WHERE id = 'liu-qi';
UPDATE persons SET bio = '可以指： * 劉邵 (河間王)，两汉之际河間王 * 刘劭 (三国)，曹魏时期政治人物 * 刘劭 (晋朝) * 刘劭 (南北朝)（424年－453年），中国南北朝時期劉宋的第四位皇帝。' WHERE id = 'liu-shao';
UPDATE persons SET bio = '南汉中宗，残暴，南汉由盛转衰。在南汉（943年—958年）在位。' WHERE id = 'liu-sheng';
UPDATE persons SET bio = '劉（），漢朝皇帝，其正式諡號為「孝元皇帝」，後世省略「孝」字稱「漢元帝」。汉宣帝长子，生于民间，母恭哀皇后许平君。' WHERE id = 'liu-shi';
UPDATE persons SET bio = '劉欣（），出生于定陶（今山东省菏泽市定陶区），漢朝皇帝，在位6年，其正式諡號為「孝哀皇帝」，後世省略「孝」字稱「漢哀帝」。劉欣是汉元帝孙，汉成帝弟定陶恭王刘康之子，母丁氏。' WHERE id = 'liu-xin';
UPDATE persons SET bio = '南汉高祖，据岭南。在南汉（917年—942年）在位。' WHERE id = 'liu-yan';
UPDATE persons SET bio = '可以指： * 西汉前少帝 （前188—前184年）在位。* 西汉后少帝 （前184—前180年）在位。' WHERE id = 'liu-yi-shao';
UPDATE persons SET bio = '小字车兵，彭城綏輿里（今安徽省蕭縣）人。中国南北朝時期宋朝的第二位皇帝，宋武帝刘裕长子，母親是夫人張氏。' WHERE id = 'liu-yifu';
